//! Stored sessions, and the one question this side actually asks.
//!
//! THE DRIVER NEVER TYPES A CREDENTIAL. That is a consequence of never logging in unattended, and it
//! is the strongest property in this whole layer: a person signs in with their own browser, the
//! resulting session is stored, and everything automated only ever REUSES one. So no code path here
//! reads a password, and there is no password for a bug in it to leak. `bsc secret` still records
//! which pairings exist and whether they last worked — metadata, which is what it is for.
//!
//! # This is NARROWER than the TypeScript policy, deliberately
//!
//! `@/features/finance/lib/connection` decides among six actions — login, wait, hand over, stop. This
//! answers ONE question: may an unattended fetch happen right now? It is not a port of that function
//! and must not become one; two copies of a six-way decision in two languages is a divergence waiting
//! to happen, and the divergence would be in the direction of doing something unsafe.
//!
//! The contract between them is one-way and CONSERVATIVE: this may answer `Go` only where the general
//! policy would say `use-session`. Every other case is somebody's problem, not this function's, and it
//! says so rather than deciding. That asymmetry is why the narrow version is safe to have twice.
use std::time::{SystemTime, UNIX_EPOCH};

/// What happened last time something touched this institution.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Outcome {
    /// Signed in and got what we came for.
    Ok,
    /// The institution was NOT REACHED. Says nothing about the credential.
    Transport,
    /// The credential was REJECTED. Never retried, by anything, ever.
    Auth,
    /// MFA or a device check. A person is needed.
    Challenge,
    /// Signed in, but the page was not the page we expected.
    Layout,
    /// The institution says the account is locked.
    Locked,
}

impl Outcome {
    pub fn as_str(self) -> &'static str {
        match self {
            Outcome::Ok => "ok",
            Outcome::Transport => "transport",
            Outcome::Auth => "auth",
            Outcome::Challenge => "challenge",
            Outcome::Layout => "layout",
            Outcome::Locked => "locked",
        }
    }

    pub fn parse(s: &str) -> Option<Outcome> {
        Some(match s {
            "ok" => Outcome::Ok,
            "transport" => Outcome::Transport,
            "auth" => Outcome::Auth,
            "challenge" => Outcome::Challenge,
            "layout" => Outcome::Layout,
            "locked" => Outcome::Locked,
            _ => return None,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Attempt {
    /// `YYYY-MM-DDTHH:MM:SSZ`.
    pub at: String,
    pub outcome: Outcome,
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct SessionState {
    pub connector: String,
    /// When the person last signed in. `None` means there is nothing stored to reuse.
    pub session_since: Option<String>,
    /// Most recent LAST.
    pub attempts: Vec<Attempt>,
    /// Set by a person, cleared by a person. Nothing automated writes this false.
    pub locked_out: bool,
}

/// The answer, and only ever about an UNATTENDED fetch.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FetchVerdict {
    /// A stored session is usable right now.
    Go,
    /// Nothing is wrong; there is simply no session to reuse, and establishing one is attended.
    NeedsPerson(String),
    /// Something IS wrong and a person has to deal with the institution before anything retries.
    Blocked(String),
}

impl FetchVerdict {
    pub fn is_go(&self) -> bool {
        matches!(self, FetchVerdict::Go)
    }

    pub fn reason(&self) -> &str {
        match self {
            FetchVerdict::Go => "a stored session is still young enough to reuse",
            FetchVerdict::NeedsPerson(r) | FetchVerdict::Blocked(r) => r,
        }
    }
}

/// Seconds since the epoch for `YYYY-MM-DDTHH:MM:SSZ`, or `None` if it is not that.
///
/// Written out rather than pulled in: a date crate here would be a dependency the whole binary pays
/// for so that one comparison can be made, and the civil-days arithmetic is a known, closed form.
pub fn epoch_seconds(iso: &str) -> Option<i64> {
    let b = iso.as_bytes();
    if b.len() < 19 || b[4] != b'-' || b[7] != b'-' || (b[10] != b'T' && b[10] != b' ') || b[13] != b':' || b[16] != b':' {
        return None;
    }
    let num = |a: usize, z: usize| iso.get(a..z)?.parse::<i64>().ok();
    let (y, mo, d) = (num(0, 4)?, num(5, 7)?, num(8, 10)?);
    let (h, mi, s) = (num(11, 13)?, num(14, 16)?, num(17, 19)?);
    if !(1..=12).contains(&mo) || !(1..=31).contains(&d) || h > 23 || mi > 59 || s > 60 {
        return None;
    }
    // Howard Hinnant's days_from_civil: exact, branch-light, and correct across the leap rules.
    let y = if mo <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = (mo + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    let days = era * 146_097 + doe - 719_468;
    Some(days * 86_400 + h * 3600 + mi * 60 + s)
}

/// `YYYY-MM-DDTHH:MM:SSZ` for right now — the only place a clock is read, so everything below it can
/// be handed a fixed time and tested.
pub fn now_iso() -> String {
    let secs = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0);
    iso_from_epoch(secs)
}

pub fn iso_from_epoch(secs: i64) -> String {
    let (days, rem) = (secs.div_euclid(86_400), secs.rem_euclid(86_400));
    let z = days + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    format!("{y:04}-{m:02}-{d:02}T{:02}:{:02}:{:02}Z", rem / 3600, (rem % 3600) / 60, rem % 60)
}

pub const DEFAULT_TTL_HOURS: i64 = 168;

/// Whether the stored session is young enough to reuse.
///
/// A FUTURE-DATED session is NOT fresh. Clock skew or a bad write would otherwise make one read as
/// fresh forever, so nothing would re-authenticate and every fetch after it would quietly return
/// nothing — a silent stop, which is the worst failure available here.
pub fn session_is_fresh(state: &SessionState, as_of: &str, ttl_hours: i64) -> bool {
    let (Some(since), Some(now)) = (state.session_since.as_deref().and_then(epoch_seconds), epoch_seconds(as_of))
    else {
        return false;
    };
    let age = now - since;
    age >= 0 && age < ttl_hours * 3600
}

/// May an unattended fetch happen right now?
///
/// The stopping cases are checked FIRST and unconditionally, so no amount of session freshness can
/// talk this into acting on a connection a person needs to look at.
pub fn may_fetch_unattended(state: &SessionState, as_of: &str, ttl_hours: i64) -> FetchVerdict {
    if state.locked_out {
        return FetchVerdict::Blocked(
            "the account is locked — only the institution clears that, and nothing here will try again in the meantime".into(),
        );
    }
    match state.attempts.last().map(|a| a.outcome) {
        Some(Outcome::Locked) => {
            return FetchVerdict::Blocked("the institution reported the account locked on the last attempt".into())
        }
        Some(Outcome::Auth) => {
            // Never, and not because of a count — because of what it was. Nothing here retries a
            // rejected credential, and no elapsed time changes that.
            return FetchVerdict::Blocked(
                "the credential was rejected last time — a second automated attempt is how an account gets locked. Update it with `bsc secret put`, then sign in once by hand.".into(),
            )
        }
        Some(Outcome::Challenge) => {
            return FetchVerdict::Blocked(
                "a verification challenge is waiting — sign in by hand to clear it; nothing here will try to route around one".into(),
            )
        }
        Some(Outcome::Layout) => {
            return FetchVerdict::Blocked(
                "the page was not what it was last time — a fetch against a changed layout reads plausible nonsense, so it stops rather than guessing".into(),
            )
        }
        _ => {}
    }

    if session_is_fresh(state, as_of, ttl_hours) {
        return FetchVerdict::Go;
    }
    FetchVerdict::NeedsPerson(match state.session_since {
        // Nothing is WRONG here. There is simply nothing to reuse, and establishing one is attended
        // by design — so this is a different answer from `Blocked`, and the caller should read it
        // as "your turn", not "something broke".
        Some(_) => "the stored session has aged out — sign in once and it is good for another week".into(),
        None => "no stored session — sign in once by hand and everything after that is unattended".into(),
    })
}

/// Record what an attempt did. Append-only: an attempt history that can be rewritten is not evidence,
/// and the `auth` entry is precisely the one something would be tempted to remove.
pub fn record(state: &mut SessionState, outcome: Outcome, at: &str) {
    state.attempts.push(Attempt { at: at.to_string(), outcome });
    if outcome == Outcome::Locked {
        state.locked_out = true;
    }
    if outcome == Outcome::Ok && state.session_since.is_none() {
        state.session_since = Some(at.to_string());
    }
}

/// Stamp a session as established — what the attended sign-in reports back.
pub fn established(state: &mut SessionState, at: &str) {
    state.session_since = Some(at.to_string());
    state.attempts.push(Attempt { at: at.to_string(), outcome: Outcome::Ok });
}


// ─────────────────────────────────────────────────────────────────────────────────────────────────
// The wire shape
//
// VALUES, not IO. The file handling belongs to the caller; what is worth pinning here is that a
// round trip loses nothing — a session store that silently drops the `auth` attempt on reload would
// re-enable exactly the retry the policy above exists to forbid.

/// Every state as one JSON value, keyed by connector.
pub fn to_json(states: &[SessionState]) -> serde_json::Value {
    serde_json::Value::Object(
        states
            .iter()
            .map(|s| {
                (
                    s.connector.clone(),
                    serde_json::json!({
                        "sessionSince": s.session_since,
                        "lockedOut": s.locked_out,
                        "attempts": s.attempts.iter().map(|a| serde_json::json!({
                            "at": a.at,
                            "outcome": a.outcome.as_str(),
                        })).collect::<Vec<_>>(),
                    }),
                )
            })
            .collect(),
    )
}

/// Read them back. An outcome nobody recognises is DROPPED with the attempt it belongs to rather
/// than defaulting to `ok` — a future version writing an outcome this one has never heard of must
/// not have it read as "everything is fine".
pub fn from_json(value: &serde_json::Value) -> Vec<SessionState> {
    let Some(obj) = value.as_object() else { return Vec::new() };
    let mut out: Vec<SessionState> = obj
        .iter()
        .map(|(connector, v)| SessionState {
            connector: connector.clone(),
            session_since: v.get("sessionSince").and_then(|x| x.as_str()).map(str::to_string),
            locked_out: v.get("lockedOut").and_then(|x| x.as_bool()).unwrap_or(false),
            attempts: v
                .get("attempts")
                .and_then(|x| x.as_array())
                .map(|xs| {
                    xs.iter()
                        .filter_map(|a| {
                            Some(Attempt {
                                at: a.get("at")?.as_str()?.to_string(),
                                outcome: Outcome::parse(a.get("outcome")?.as_str()?)?,
                            })
                        })
                        .collect()
                })
                .unwrap_or_default(),
        })
        .collect();
    out.sort_by(|a, b| a.connector.cmp(&b.connector));
    out
}

/// The state for one connector, or a blank one — a connector nobody has touched is not an error.
pub fn state_for(states: &[SessionState], connector: &str) -> SessionState {
    states
        .iter()
        .find(|s| s.connector == connector)
        .cloned()
        .unwrap_or_else(|| SessionState { connector: connector.to_string(), ..Default::default() })
}

/// Replace one connector's state, keeping every other.
pub fn upsert(states: &mut Vec<SessionState>, next: SessionState) {
    match states.iter_mut().find(|s| s.connector == next.connector) {
        Some(slot) => *slot = next,
        None => states.push(next),
    }
    states.sort_by(|a, b| a.connector.cmp(&b.connector));
}

#[cfg(test)]
mod tests {
    use super::*;

    // SYNTHETIC FIXTURES ONLY. No real credential, account or session belongs in this repo.
    const NOW: &str = "2026-07-01T12:00:00Z";

    fn ago(hours: i64) -> String {
        iso_from_epoch(epoch_seconds(NOW).unwrap() - hours * 3600)
    }

    fn state(session_hours_ago: Option<i64>, attempts: &[Outcome]) -> SessionState {
        SessionState {
            connector: "discover".into(),
            session_since: session_hours_ago.map(ago),
            attempts: attempts.iter().map(|o| Attempt { at: ago(1), outcome: *o }).collect(),
            locked_out: false,
        }
    }

    #[test]
    fn epoch_round_trips_through_iso() {
        for iso in ["1970-01-01T00:00:00Z", "2000-02-29T13:45:01Z", "2026-07-01T12:00:00Z", "2100-03-01T00:00:00Z"] {
            assert_eq!(iso_from_epoch(epoch_seconds(iso).unwrap()), iso, "{iso}");
        }
    }

    #[test]
    fn epoch_gets_the_leap_rules_right() {
        // 2000 is a leap year and 1900 is not — the century rule is exactly where a hand-rolled date
        // conversion goes wrong, and one day of drift here silently mis-ages every session.
        let day = 86_400;
        assert_eq!(
            epoch_seconds("2000-03-01T00:00:00Z").unwrap() - epoch_seconds("2000-02-28T00:00:00Z").unwrap(),
            2 * day
        );
        assert_eq!(
            epoch_seconds("1900-03-01T00:00:00Z").unwrap() - epoch_seconds("1900-02-28T00:00:00Z").unwrap(),
            day
        );
    }

    #[test]
    fn epoch_refuses_what_is_not_a_timestamp() {
        for bad in ["", "2026-07-01", "2026-07-01T12:00", "not a date", "2026-13-01T00:00:00Z", "2026-07-01T25:00:00Z"] {
            assert!(epoch_seconds(bad).is_none(), "{bad}");
        }
    }

    #[test]
    fn a_young_session_is_fresh_and_an_old_one_is_not() {
        assert!(session_is_fresh(&state(Some(24), &[]), NOW, DEFAULT_TTL_HOURS));
        assert!(!session_is_fresh(&state(Some(24 * 30), &[]), NOW, DEFAULT_TTL_HOURS));
        assert!(!session_is_fresh(&state(None, &[]), NOW, DEFAULT_TTL_HOURS));
    }

    #[test]
    fn a_future_dated_session_fails_closed() {
        // "Fresh forever" would stop anything ever re-authenticating, and every fetch after it would
        // quietly return nothing. A silent stop is the worst failure shape available here.
        let s = state(Some(-48), &[]);
        assert!(!session_is_fresh(&s, NOW, DEFAULT_TTL_HOURS));
        assert!(!may_fetch_unattended(&s, NOW, DEFAULT_TTL_HOURS).is_go());
    }

    #[test]
    fn a_rejected_credential_blocks_forever_however_fresh_the_session_looks() {
        // The stopping cases are checked before anything else precisely so this cannot be talked
        // out of stopping. It is not a count that stops it — it is what the outcome WAS.
        let s = state(Some(1), &[Outcome::Auth]);
        let v = may_fetch_unattended(&s, NOW, DEFAULT_TTL_HOURS);
        assert!(matches!(v, FetchVerdict::Blocked(_)));
        assert!(v.reason().contains("how an account gets locked"), "{}", v.reason());
        assert!(v.reason().contains("bsc secret put"), "{}", v.reason());
    }

    #[test]
    fn a_challenge_a_layout_change_and_a_lock_all_block() {
        for outcome in [Outcome::Challenge, Outcome::Layout, Outcome::Locked] {
            let v = may_fetch_unattended(&state(Some(1), &[outcome]), NOW, DEFAULT_TTL_HOURS);
            assert!(matches!(v, FetchVerdict::Blocked(_)), "{outcome:?} did not block");
        }
        assert!(matches!(
            may_fetch_unattended(&SessionState { locked_out: true, ..state(Some(1), &[]) }, NOW, DEFAULT_TTL_HOURS),
            FetchVerdict::Blocked(_)
        ));
    }

    #[test]
    fn a_transport_failure_does_not_block_a_usable_session() {
        // The institution was not reached. That says nothing about the credential, and a stored
        // session is no less valid for it.
        let v = may_fetch_unattended(&state(Some(1), &[Outcome::Transport]), NOW, DEFAULT_TTL_HOURS);
        assert!(v.is_go(), "{}", v.reason());
    }

    #[test]
    fn no_session_is_your_turn_rather_than_something_broke() {
        // NeedsPerson and Blocked are different answers on purpose: one is the design working, the
        // other is something to go and look at. Collapsing them would make the normal case alarming.
        let v = may_fetch_unattended(&state(None, &[]), NOW, DEFAULT_TTL_HOURS);
        assert!(matches!(v, FetchVerdict::NeedsPerson(_)));
        assert!(v.reason().contains("everything after that is unattended"), "{}", v.reason());

        let aged = may_fetch_unattended(&state(Some(24 * 30), &[]), NOW, DEFAULT_TTL_HOURS);
        assert!(matches!(aged, FetchVerdict::NeedsPerson(_)));
        assert!(aged.reason().contains("aged out"), "{}", aged.reason());
    }

    #[test]
    fn a_fresh_session_goes() {
        assert!(may_fetch_unattended(&state(Some(24), &[Outcome::Ok]), NOW, DEFAULT_TTL_HOURS).is_go());
    }

    #[test]
    fn recording_a_lock_sets_the_flag_a_person_has_to_clear() {
        let mut s = state(Some(1), &[]);
        record(&mut s, Outcome::Locked, NOW);
        assert!(s.locked_out);
        // And it stays set even when a later attempt looks fine — only a person clears it.
        record(&mut s, Outcome::Ok, NOW);
        assert!(s.locked_out);
        assert!(matches!(may_fetch_unattended(&s, NOW, DEFAULT_TTL_HOURS), FetchVerdict::Blocked(_)));
    }

    #[test]
    fn recording_is_append_only() {
        // An attempt history that can be rewritten is not evidence, and the `auth` entry is exactly
        // the one something would be tempted to drop.
        let mut s = state(None, &[]);
        record(&mut s, Outcome::Auth, NOW);
        record(&mut s, Outcome::Transport, NOW);
        assert_eq!(s.attempts.len(), 2);
        assert_eq!(s.attempts[0].outcome, Outcome::Auth);
    }

    #[test]
    fn establishing_a_session_is_what_the_attended_sign_in_reports() {
        let mut s = state(None, &[]);
        assert!(!may_fetch_unattended(&s, NOW, DEFAULT_TTL_HOURS).is_go());
        established(&mut s, NOW);
        assert_eq!(s.session_since.as_deref(), Some(NOW));
        assert!(may_fetch_unattended(&s, NOW, DEFAULT_TTL_HOURS).is_go());
    }


    #[test]
    fn a_round_trip_loses_nothing_that_matters() {
        // A store that silently dropped the `auth` attempt on reload would re-enable exactly the
        // retry this module exists to forbid.
        let mut a = state(Some(2), &[Outcome::Transport, Outcome::Auth]);
        a.locked_out = true;
        let b = state(None, &[]);
        let back = from_json(&to_json(&[a.clone(), SessionState { connector: "chase".into(), ..b }]));
        assert_eq!(back.len(), 2);
        let discover = state_for(&back, "discover");
        assert_eq!(discover, a);
        assert!(matches!(may_fetch_unattended(&discover, NOW, DEFAULT_TTL_HOURS), FetchVerdict::Blocked(_)));
    }

    #[test]
    fn an_outcome_from_the_future_is_dropped_rather_than_read_as_ok() {
        // A later version writing an outcome this one has never heard of must not have it read as
        // "everything is fine" — that is the one default that could unblock a blocked connection.
        let raw = serde_json::json!({
            "discover": { "lockedOut": false, "attempts": [ { "at": NOW, "outcome": "quarantined" } ] }
        });
        assert_eq!(from_json(&raw)[0].attempts.len(), 0);
    }

    #[test]
    fn a_connector_nobody_has_touched_is_blank_rather_than_an_error() {
        let s = state_for(&[], "wells-fargo");
        assert_eq!(s.connector, "wells-fargo");
        assert!(s.attempts.is_empty());
        assert!(!s.locked_out);
        assert!(matches!(may_fetch_unattended(&s, NOW, DEFAULT_TTL_HOURS), FetchVerdict::NeedsPerson(_)));
    }

    #[test]
    fn upsert_replaces_one_and_keeps_the_rest() {
        let mut states = vec![state(Some(1), &[]), SessionState { connector: "chase".into(), ..Default::default() }];
        upsert(&mut states, SessionState { connector: "discover".into(), locked_out: true, ..Default::default() });
        assert_eq!(states.len(), 2);
        assert!(state_for(&states, "discover").locked_out);
        assert_eq!(state_for(&states, "chase").connector, "chase");
    }

    #[test]
    fn rubbish_in_the_store_is_no_states_rather_than_a_panic() {
        assert_eq!(from_json(&serde_json::json!([])).len(), 0);
        assert_eq!(from_json(&serde_json::json!("nonsense")).len(), 0);
        assert_eq!(from_json(&serde_json::json!({ "discover": 3 })).len(), 1);
    }

    #[test]
    fn every_outcome_round_trips_through_its_name() {
        for o in [Outcome::Ok, Outcome::Transport, Outcome::Auth, Outcome::Challenge, Outcome::Layout, Outcome::Locked] {
            assert_eq!(Outcome::parse(o.as_str()), Some(o));
        }
        assert_eq!(Outcome::parse("succeeded"), None);
    }
}
